(()=>{'use strict';
const M=window.Manarat,$=id=>document.getElementById(id),esc=M.esc;
const endpoint='https://yltlzogrhwvnmxcnaesu.supabase.co/functions/v1/school-api';
const adminPanel=new URLSearchParams(location.search).get('adminPanel');
if(adminPanel)document.body.classList.add('admin-embedded');
const KEY='sb_publishable_W-XxH2FTvSZq66b-eHt-TQ_a8ZuqGRD';
const games={race:['🏎️','سباق السيارات'],football:['⚽','كرة القدم'],basketball:['🏀','كرة السلة'],volleyball:['🏐','الكرة الطائرة'],bowling:['🎳','البولينج'],fishing:['🎣','صيد الأسماك'],puzzle:['🧩','كشف الصورة'],classic:['✦','تحدّي المعرفة']};
const types={multiple_choice:'اختيار من متعدد',true_false:'صح وخطأ',open_text:'مقالي',matching:'مطابقة',connecting:'توصيل',ordering:'ترتيب',classification:'تصنيف',puzzle_image:'بازل الصور'};
function gameIcon(k){const paths={race:'<path d="M3 15l2-6h14l2 6v4H3zM7 9l2-4h6l2 4M6 19v2m12-2v2M6 14h2m8 0h2"/>',football:'<circle cx="12" cy="12" r="9"/><path d="M12 7l5 4-2 6H9l-2-6zM12 3v4m9 5l-4-1m-2 6l3 3M9 17l-3 3M3 12l4-1"/>',basketball:'<circle cx="12" cy="12" r="9"/><path d="M3 12h18M12 3v18M5 5q12 7 0 14M19 5q-12 7 0 14"/>',volleyball:'<circle cx="12" cy="12" r="9"/><path d="M12 3q-4 6 0 9t0 9M3 12q5-3 9 0M12 12q3-5 8-6M5 6q3 6 2 12"/>',bowling:'<path d="M8 3h4v5l3 9q1 4-5 4t-5-4l3-9zM8 7h4"/><circle cx="18" cy="17" r="4"/><path d="M17 16h.1m2 0h.1"/>',fishing:'<path d="M14 3v9q0 5-5 5t-4-5M5 12l2 2M4 5l16-3"/><path d="M12 20q4-6 8-2l3-2v6l-3-2q-4 3-8 0z"/>',puzzle:'<path d="M4 4h6q-2 6 3 5t2-5h5v6q-6-2-5 3t5 2v5h-6q2-6-3-5t-2 5H4v-6q6 2 5-3t-5-2z"/>',classic:'<path d="M12 2l3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true" width="25" height="25" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round">${paths[k]||paths.classic}</svg>`;}
let config={name:'مدرسة أبو عبيد الإعدادية للبنين',subtitle:'منصة التعلّم التفاعلي',primary:'#8a1538',background:'#f8f6f4',hero:'تعلّم بطريقتك. وتقدّم كل يوم.',description:'مساحة واحدة تجمع معلمي المدرسة وطلابها.',socials:[],sections:['games','videos','about']},data=null,tab='games',assignment=null,play=null,selected='race',noticeTimer,settingsDraft;
function gameHUD(){if(!play||!assignment)return '';const maximum=play.questions.reduce((n,q)=>n+Math.max(1,Math.min(100,Number(q.points)||10)),0),score=maximum?Math.round((play.points||0)*100/maximum):0;return `<header class="game-session-hud"><div class="session-identity"><span>${esc(config.name)}</span><strong>${esc(assignment.title)}</strong><div class="session-details"><span>${esc(games[play.template]?.[1]||'')}</span><span>المادة: ${esc(assignment.subject||'غير محددة')}</span>${assignment.teacher?`<span>المعلم: ${esc(assignment.teacher)}</span>`:''}${assignment.class_name?`<span>${esc(assignment.class_name)}</span>`:''}</div></div><div class="session-scores"><div><small>النقاط التعليمية</small><b>${play.points||0}<em> / ${maximum}</em></b></div><div><small>${assignment.mode==='group'?'النمط':play.pendingCount?'الدرجة المبدئية':'الدرجة'}</small><b>${assignment.mode==='group'?'جماعي':score+'%'}</b></div><div><small>الإجابات</small><b>${play.completed||0}<em> / ${play.questions.length}</em></b></div></div>${play.demo?'<p class="session-note">تجربة تدريبية — لا تُسجّل نتائجها في حسابات الطلاب.</p>':play.pendingCount?'<p class="session-note">توجد إجابات تنتظر تصحيح المعلم.</p>':''}</header>`;}
function updateGameHUD(){document.querySelectorAll('.game-session-hud').forEach(el=>el.outerHTML=gameHUD());}
function startDemo(sport){if(!['race','football','basketball','bowling','volleyball','fishing','puzzle','classic'].includes(sport))return home();const questions=[{id:'demo1',type:'multiple_choice',text:'كم يساوي حاصل ضرب ٣ × ٤؟',options:['٧','١٢','١٦'],correct:1,points:10},{id:'demo2',type:'multiple_choice',text:'ما الكوكب الذي نعيش عليه؟',options:['الأرض','المريخ','زحل'],correct:0,points:10},{id:'demo3',type:'multiple_choice',text:'أيّ هذه الكلمات تدل على جمع؟',options:['كتاب','طالب','أشجار'],correct:2,points:10}];assignment={title:'تجربة '+games[sport][1],subject:'معارف عامة',teacher:'',class_name:'',mode:'demo',settings:{templates:[sport],types:['multiple_choice']},videos:[]};play={id:'demo-'+sport,secret:'local-demo',demo:true,questions,index:0,correct:0,points:0,completed:0,pendingCount:0,template:sport,threshold:70};if(sport==='race')renderRace();else renderSport();}
async function api(action,payload={}){if(play?.demo&&payload.id===play.id){if(action==='answer'){const q=play.questions.find(q=>q.id===payload.question);if(!q)throw new Error('سؤال غير صالح.');const correct=payload.value===q.correct;return {correct,pending:false,points:correct?q.points:0,max:q.points,feedback:correct?'إجابة صحيحة، أحسنت!':'إجابة غير صحيحة، واصل المحاولة.',explanation:''};}if(action==='finish'){const total=play.questions.reduce((n,q)=>n+q.points,0);const score=Math.round((play.points||0)/total*100);return {score,pending:false,passed:score>=70,group:false};}if(action==='leaderboard')return [];}
if(adminPanel&&window.parent&&window.parent!==window){try{const broker=window.parent.ManaratAdminRequests;if(broker)return await broker.request(action,payload);}catch(e){throw e;}}if(action!=='settings')await M.ensureFreshSession();const token=M.authSession()?.access_token;const res=await fetch(endpoint,{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify({action,...payload})});const j=await res.json();if(!res.ok)throw new Error(j.error||'تعذر الاتصال.');return j;}
function notice(msg){$('notice').textContent=msg;$('notice').style.display='block';clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').style.display='none',5500);}
async function run(fn,button){if(button)button.disabled=true;try{return await fn();}catch(e){notice(e.message||'تعذر تنفيذ العملية.');if($('app').querySelector('.loading'))show('<section class="card"><h2>تعذر فتح الصفحة</h2><p>'+esc(e.message)+'</p><a class="button" href="index.html">العودة للرئيسية</a></section>');}finally{if(button)button.disabled=false;}}
function show(html){document.body.classList.toggle?.('playing-game',html.includes('class="game-session-hud"'));$('app').innerHTML=html;window.scrollTo(0,0);}
function dialog(html){$('modal').classList.toggle('scene-question',!!play&&['volleyball','fishing','puzzle','classic'].includes(play.template)&&html.includes('game-layout'));$('modalContent').innerHTML=html;if(!$('modal').open)$('modal').showModal();}
function close(){$('modal').close();}
function button(text,action,id='',cls=''){return `<button type="button" class="${cls}" data-action="${action}" data-id="${esc(id)}">${text}</button>`;}
function field(label,id,value='',type='text'){return `<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}">`;}
function applyBrand(c){document.documentElement.style.setProperty('--primary',c.primary);document.documentElement.style.setProperty('--bg',c.background);$('brandName').textContent=c.name;$('brandSubtitle').textContent=c.subtitle;document.title=c.name+' | منصة التعلم';$('brandMark').innerHTML=c.logo?`<img alt="شعار المدرسة" src="${esc(c.logo)}">`:'أ';$('footer').innerHTML=`<span>${esc(c.footerText||c.name+' · مساحة للتعلّم والإنجاز')}</span><div class="row">${(c.socials||[]).filter(s=>s.visible!==false&&/^https:\/\//.test(s.url)).map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)}</a>`).join('')}</div>`;}
async function navigation(){if($('adminLink')){$('adminLink').hidden=true;if(M.isAuthenticated())try{const p=await api('profile');$('adminLink').hidden=!p.admin;}catch{}}$('dashboardLink').hidden=!M.isAuthenticated();$('loginLink').textContent=M.isAuthenticated()?'خروج':'دخول المعلم';}
function home(){const sections={games:`<section><div class="section-head"><div><h2>اختر ملعبك. وابدأ التحدّي.</h2><p>اختر التجربة التي تحبها من الألعاب التي يتيحها معلمك.</p></div><span class="tag">8 تجارب تعلّم</span></div><div class="grid games-gallery">${Object.entries(games).map(([k,g])=>`<article class="card game-cover-card"><div class="game-cover" data-scene="${k}"><img src="assets/game-covers/${k}.svg" alt="مشهد ${g[1]}" width="640" height="360" loading="lazy" decoding="async"><span class="cover-number">0${Object.keys(games).indexOf(k)+1}</span></div><div class="game-cover-body"><h3>${g[1]}</h3><p class="muted">${({race:'تقدّم بسيارتك مع كل إجابة صحيحة.',football:'أجب وسدّد نحو المرمى.',basketball:'حوّل إجاباتك إلى رميات ناجحة.',volleyball:'ارسل الكرة واجمع نقاط فريقك.',bowling:'أسقط القوارير بإجاباتك الصحيحة.',fishing:'اجمع صيدك مع كل فكرة تتعلمها.',puzzle:'اكشف أجزاء الصورة خطوة بخطوة.',classic:'ركّز في الأسئلة وتابع تقدمك.'})[k]}</p>${['race','football','basketball','bowling','volleyball','fishing','puzzle','classic'].includes(k)?`<a class="button quiet" href="index.html?demo=${k}">${k==='race'?'جرّب السباق':'جرّب اللعبة'} ←</a>`:''}</div></article>`).join('')}</div></section>`,videos:`<section class="card" style="margin-top:26px"><div class="row"><span class="card-icon">▷</span><div><h3>شاهد، افهم، ثم جرّب</h3><p class="muted">تجد فيديوهات المادة التي أضافها معلمك داخل رابط المهمة، قبل أن تبدأ اللعب.</p></div></div></section>`,about:`<section class="section-head"><div><h2>من نحن</h2><p>${esc(config.about||config.description)}</p>${config.contactText?`<h3>تواصل معنا</h3><p>${esc(config.contactText)}</p>`:''}<div class="row">${(config.socials||[]).filter(s=>s.visible!==false&&/^https:\/\//.test(s.url)).map(s=>`<a class="button quiet" href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)}</a>`).join('')}</div></div></section>`};show(`<section class="hero"><div><span class="eyebrow">مدرستنا · تعلّم تفاعلي · إنجاز يومي</span><h1>${esc(config.hero)}</h1><p>${esc(config.description)}</p><div class="row">${button('دخول مساحة المعلم ←','dashboard')}${button('لديّ رابط أو رمز مهمة','joinFocus','','outline')}</div></div><div class="hero-showcase" aria-hidden="true"><div class="hero-scene" data-scene="football"><img src="assets/game-covers/football.svg" alt="" width="640" height="360" decoding="async"></div><div class="hero-showcase-caption"><span class="hero-live">تعلّم تفاعلي</span><h3>المعرفة تصنع الفوز.</h3><p>ألعاب، فيديوهات، وتحدّيات تجمع المتعة بالتعلّم.</p></div></div></section><form id="joinForm" class="join row"><label for="joinCode" style="margin:0;font-weight:700">ابدأ مهمتك</label><input id="joinCode" autocomplete="off" placeholder="الصق رابط المهمة أو رمز الدخول" required><button>انضمّ للمهمة ←</button><span class="help">الدخول للطالب بالاسم فقط</span></form>${config.sections.map(s=>sections[s]||'').join('')}`);window.ManaratCovers?.refresh();}
function auth(signup=false){show(`<section class="auth card"><span class="eyebrow">مساحة المعلمين</span><h1>${signup?'أنشئ حسابك':'أهلًا بعودتك'}</h1><p class="muted">${signup?'اسم مستخدم وكلمة مرور؛ لا تحتاج إلى بريد إلكتروني.':'أدخل اسم المستخدم. يمكن للأدمن استخدام بريده الحالي.'}</p><form id="authForm" data-signup="${signup}">${signup?field('الاسم الكامل','fullName'):''}${field('اسم المستخدم'+(signup?'':' أو بريد الأدمن'),'username')}${field('كلمة المرور','password','','password')}<p class="help">${signup?'8 أحرف على الأقل. اسم المستخدم فريد ولا يحتوي على مسافات.':'نسيت كلمة المرور؟ تواصل مع إدارة المدرسة لإعادة تعيينها.'}</p><button style="width:100%">${signup?'إنشاء الحساب':'تسجيل الدخول'}</button></form><div style="margin-top:18px">${button(signup?'لديّ حساب بالفعل':'إنشاء حساب معلم',signup?'login':'signup','','quiet')}</div></section>`);$('username').autocomplete='username';$('password').autocomplete=signup?'new-password':'current-password';}
async function dashboard(){if(!M.isAuthenticated())return auth();if(!data)show('<p class="loading">جارٍ تحميل مساحتك…</p>');data=adminPanel==='settings'?{profile:await api('profile')}:await api('dashboard',adminPanel?{panel:adminPanel}:{});if($('adminLink'))$('adminLink').hidden=!data.profile.admin;if(adminPanel){if(!data.profile.admin)throw new Error('هذه اللوحة متاحة للإدارة فقط.');tab=['settings','teachers','students','reports','assignments','videos','games'].includes(adminPanel)?adminPanel:'settings';}renderDashboard();}
function renderDashboard(){if(adminPanel){show('<section id="panel"></section>');renderPanel();return;}const group=data.sessions.filter(s=>s.mode==='group'),individual=data.sessions.filter(s=>s.mode!=='group'&&s.finished_at);show(`<div class="section-head" style="margin-top:0"><div><span class="eyebrow">${data.profile.admin?'إدارة المدرسة':'مساحة المعلم'}</span><h1 style="margin:5px 0">أهلًا، ${esc(data.profile.name)}</h1><p>نظّم المحتوى، فعّل التعلّم، وتابع أثره.</p></div>${data.profile.admin?'<a class="button" href="admin/admin.html">لوحة التحكم ←</a>':''}<a class="button quiet" href="teacher/create-game.html">＋ إنشاء لعبة</a></div><div class="stats"><div class="card stat"><b>${data.games.length}</b><span>لعبة أنشئت</span></div><div class="card stat"><b>${new Set(data.sessions.map(s=>s.assignment_id)).size}</b><span>مهمة تم تشغيلها</span></div><div class="card stat"><b>${group.length}</b><span>جلسة جماعية في الصف</span></div><div class="card stat"><b>${individual.length}</b><span>محاولة فردية مكتملة</span></div></div><div class="tabs">${[['games','ألعابي'],['assignments','المهمات والواجبات'],['videos','فيديوهاتي'],['reports','سجل الإنجاز'],...(data.profile.admin?[['teachers','المعلمون'],['settings','هوية المدرسة']]:[])].map(([k,t])=>button(t,'tab',k,k===tab?'active':'')).join('')}</div><section id="panel"></section>`);renderPanel();}
const empty=(s)=>`<div class="empty">${s}</div>`;
function renderPanel(){const p=$('panel');if(tab==='games')p.innerHTML=data.games.length?`<div class="grid">${data.games.map(g=>`<article class="card"><span class="tag">${esc(g.subject||'مادة تعليمية')}</span><h3>${esc(g.title)}</h3><p class="muted">${(g.data.questions||[]).length} سؤال · ${esc(g.grade||'اختر الصف عند الإسناد')}</p><div class="row">${button('إسناد وتشغيل','assign',g.id)}<a class="button quiet" href="teacher/create-game.html?edit=${encodeURIComponent(g.id)}">تحرير</a></div></article>`).join('')}</div>`:empty('ابدأ بإنشاء لعبة وأضف أسئلتك يدويًا أو بالذكاء الاصطناعي.');
if(tab==='assignments')p.innerHTML=data.assignments.length?`<div class="grid">${data.assignments.map(a=>`<article class="card"><span class="tag">${esc(a.class_name||'مهمة تعليمية')} · ${a.active?'متاحة':'متوقفة'}</span><h3>${esc(a.title)}</h3><p class="muted">${a.settings.templates.map(k=>games[k]?.[1]).join(' · ')}</p><div class="stack"><div class="row">${button('نسخ رابط الواجب','copy',a.id)}${button('تشغيل صفي','class',a.id,'quiet')}</div>${button(a.active?'إيقاف المهمة':'إعادة التفعيل','toggle',a.id,'outline')}</div></article>`).join('')}</div>`:empty('أنشئ إسنادًا من تبويب ألعابي، ثم شارك رابط الواجب مع الطلاب.');
if(tab==='videos')p.innerHTML=`<div class="section-head"><div><h2>مكتبتك التعليمية</h2><p>أضف رابط فيديو أو ارفع ملفًا واربطه بمادة أو لعبة.</p></div>${button('＋ إضافة فيديو','addVideo')}</div><div class="grid">${data.videos.map(v=>`<article class="card"><span class="tag">${esc(v.subject||'فيديو تعليمي')}</span><h3>${esc(v.title)}</h3><div class="row">${button('مشاهدة','watch',v.id,'quiet')}${button('حذف','deleteVideo',v.id,'outline')}</div></article>`).join('')}</div>`;
if(tab==='reports')renderReports();if(tab==='settings')renderSettings();if(tab==='teachers')renderAccounts();if(tab==='students')renderStudents();
}
function assignmentForm(id){const g=data.games.find(g=>g.id===id),available=[...new Set((g.data.questions||[]).map(q=>q.type))];dialog(`<h2>إسناد «${esc(g.title)}»</h2><form id="assignmentForm" data-game="${esc(id)}">${field('عنوان المهمة','assignmentTitle',g.title)}${field('الصف / الشعبة','className')}<label>الألعاب المتاحة للطالب</label><div class="check-grid">${Object.entries(games).map(([k,g])=>`<label class="check"><input type="checkbox" name="templates" value="${k}" checked>${gameIcon(k)} ${g[1]}</label>`).join('')}</div><label>أنواع الأسئلة المتاحة</label><div class="check-grid">${available.map(k=>`<label class="check"><input type="checkbox" name="types" value="${esc(k)}" checked>${types[k]||esc(k)}</label>`).join('')}</div><div class="two-col"><div>${field('درجة الاجتياز %','passingScore',70,'number')}</div><div>${field('موعد الإغلاق (اختياري)','deadline','','datetime-local')}</div></div><label class="check"><input id="leaderboard" type="checkbox" checked>إظهار قائمة الصدارة للمشاركين</label><p class="help">اللعب الجماعي يُحتسب جلسة للمعلم. الفردي فقط يُسجّل باسم الطالب ودرجته.</p><button>إنشاء رابط المهمة</button></form>`);}
function link(a){const u=new URL('index.html',location.href);u.searchParams.set('task',a.code);return u.href;}
function videoForm(){dialog(`<h2>إضافة فيديو تعليمي</h2><form id="videoForm">${field('العنوان','videoTitle')}${field('المادة','videoSubject')}${field('رابط الفيديو (يوتيوب أو ملف فيديو)','videoUrl','','url')}<label for="videoFile">أو ارفع ملف فيديو (حتى 40 MB)</label><input id="videoFile" type="file" accept="video/mp4,video/webm"><label for="videoGame">يظهر مع</label><select id="videoGame"><option value="">جميع مهماتي</option>${data.games.map(g=>`<option value="${esc(g.id)}">${esc(g.title)}</option>`).join('')}</select><button style="margin-top:18px">حفظ الفيديو</button></form>`);}
function watch(v){let u;try{u=new URL(v.url);}catch{return;}const youtube=['youtube.com','www.youtube.com','m.youtube.com','youtu.be'].includes(u.hostname);let id=u.hostname==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.match(/\/(?:embed|shorts)\/([^/]+)/)?.[1];dialog(`<h2>${esc(v.title)}</h2>${youtube&&/^[\w-]{11}$/.test(id||'')?`<iframe class="media" title="${esc(v.title)}" src="https://www.youtube-nocookie.com/embed/${id}" allow="fullscreen" allowfullscreen></iframe>`:/\.(mp4|webm)(\?|$)/i.test(v.url)?`<video class="media" controls src="${esc(v.url)}"></video>`:`<a class="button" href="${esc(v.url)}" target="_blank" rel="noopener">فتح الفيديو</a>`}`);}
function renderReports(){const selectedReport=$('reportAssignment')?.value||'',rows=data.sessions.filter(s=>s.mode!=='group'&&(!selectedReport||s.assignment_id===selectedReport));$('panel').innerHTML=`<div class="section-head"><div><h2>سجل الإنجاز الفردي</h2><p>الصف: ${rows.filter(s=>s.mode==='individual').length} محاولة · المنزل: ${rows.filter(s=>s.mode==='home').length} محاولة</p></div>${button('تصدير Excel (CSV)','export','','quiet')}</div><label for="reportAssignment">تصفية بالمهمة</label><select id="reportAssignment"><option value="">كل المهمات</option>${data.assignments.map(a=>`<option value="${a.id}" ${selectedReport===a.id?'selected':''}>${esc(a.title)} · ${esc(a.class_name)}</option>`).join('')}</select><div class="table-wrap" style="margin-top:16px"><table><thead><tr><th>الطالب</th><th>المهمة</th><th>المكان</th><th>الدرجة</th><th>الحالة</th><th>التفاصيل</th></tr></thead><tbody>${rows.map(s=>`<tr><td>${esc(s.student_name)}</td><td>${esc(data.assignments.find(a=>a.id===s.assignment_id)?.title||'')}</td><td>${s.mode==='home'?'المنزل':'الصف'}</td><td>${s.score??'—'}${s.score!==null?'%':''}</td><td>${!s.finished_at?'بدأ اللعب':s.pending?'بانتظار التصحيح':'مكتملة'}</td><td>${button('السجل','student',s.id,'quiet')} ${button('الإجابات','review',s.id,'outline')}</td></tr>`).join('')}</tbody></table></div><p class="help">الأسماء لا تُدمج تلقائيًا. يمكنك تصحيح اسم المحاولة أو ربطها بسجل طالب آخر بعد مراجعتك. تُعرض أحدث 5000 جلسة.</p>`;}
function studentRecord(id){const s=data.sessions.find(s=>s.id===id),rows=data.sessions.filter(x=>x.mode!=='group'&&x.student_key===s.student_key);dialog(`<h2>سجل ${esc(s.student_name)}</h2><p>${new Set(rows.map(x=>x.assignment_id)).size} مهمة · ${rows.length} محاولة</p><div class="stack">${rows.map(x=>`<div class="card"><b>${esc(data.assignments.find(a=>a.id===x.assignment_id)?.title||'')}</b><p>${x.score??'—'}% · ${x.pending?'بانتظار التصحيح':x.finished_at?'مكتملة':'غير مكتملة'}</p></div>`).join('')}</div><form id="renameForm" data-id="${id}">${field('تصحيح اسم هذه المحاولة','correctedName',s.student_name)}<label for="mergeKey">ربط بسجل موجود (اختياري، بعد المراجعة)</label><select id="mergeKey"><option value="">الاحتفاظ بالسجل الحالي</option>${[...new Map(data.sessions.filter(x=>x.mode!=='group'&&x.student_key!==s.student_key).map(x=>[x.student_key,x])).values()].map(x=>`<option value="${esc(x.student_key)}">${esc(x.student_name)} · ${esc(x.student_key.slice(0,8))}</option>`).join('')}</select><button style="margin-top:15px">حفظ التصحيح</button></form>`);}
async function review(id){const s=await api('review',{id});dialog(`<h2>إجابات ${esc(s.student_name||'الجلسة الجماعية')}</h2><div class="stack">${s.questions.map(q=>{const a=s.answers[q.id];return `<div class="card"><b>${esc(q.text)}</b><p class="muted">${a?esc(typeof a.value==='string'?a.value:JSON.stringify(a.value)):'لم تُجب بعد'}</p>${a?.pending?`<form class="gradeForm" data-id="${s.id}" data-q="${esc(q.id)}"><label>الدرجة من ${a.max}</label><input name="points" type="number" min="0" max="${a.max}" required><label>تغذية راجعة</label><input name="feedback"><button style="margin-top:10px">اعتماد الدرجة</button></form>`:a?`<span class="tag">${a.points} / ${a.max}</span>`:''}</div>`;}).join('')}</div>`);}

function renderAccounts(){const owner='m.samra103@gmail.com';$('panel').innerHTML=`<h2>المستخدمون والصلاحيات</h2><p class="muted">المعلم يدير محتواه ونتائج طلابه. مدير المنصة يدير جميع الحسابات والإعدادات. التسجيل متاح من صفحة الدخول.</p><div class="table-wrap"><table><thead><tr><th>الحساب</th><th>الصلاحية</th><th>الحالة</th><th>إدارة الحساب</th></tr></thead><tbody>${data.teachers.map(t=>`<tr><td><b>${esc(t.name)}</b><br><small>${esc(t.email)}</small></td><td>${t.role==='admin'?'مدير المنصة':'معلم'}</td><td>${esc(t.status)}</td><td>${t.id===data.profile.id||t.email?.toLowerCase()===owner?'حساب محمي':button(t.role==='admin'?'تحويل إلى معلم':'منح إدارة كاملة','role',t.id,'outline')+' '+button(t.status==='موقوف'?'تفعيل':'إيقاف','teacherStatus',t.id,'quiet')}${t.role==='teacher'?' '+button('إعادة كلمة المرور','reset',t.id,'quiet'):''}</td></tr>`).join('')}</tbody></table></div>`;}
function renderStudents(){const students=new Map();for(const s of data.sessions.filter(s=>s.mode!=='group')){const key=s.student_key||s.id;if(!students.has(key))students.set(key,{id:s.id,name:s.student_name,count:0,done:0});const t=students.get(key);t.count++;if(s.finished_at)t.done++;}$('panel').innerHTML=`<h2>الطلاب وسجلات التعلّم</h2><p class="muted">يدخل الطلاب بالاسم ورابط المهمة دون كلمة مرور. تحكّم في إتاحة الدخول من «المهمات والواجبات». يمكنك تصحيح الاسم وربط المحاولات من سجل الطالب.</p>${students.size?`<div class="table-wrap"><table><thead><tr><th>الطالب</th><th>المحاولات</th><th>المكتملة</th><th>السجل</th></tr></thead><tbody>${[...students.values()].map(t=>`<tr><td>${esc(t.name)}</td><td>${t.count}</td><td>${t.done}</td><td>${button('عرض وتعديل السجل','student',t.id,'quiet')}</td></tr>`).join('')}</tbody></table></div>`:empty('تظهر سجلات الطلاب بعد أول مشاركة في مهمة.')}`;}

function renderSettings(){settingsDraft=structuredClone(config);settingsDraft.socials||=[];$('panel').innerHTML=`<div class="section-head"><div><h2>البيانات الرئيسية والهوية والتواصل</h2><p>راجع المعاينة أولًا. تظهر التغييرات للجميع بعد الحفظ فقط.</p></div>${button('الإصدارات السابقة','history','','quiet')}</div><form id="settingsForm" class="two-col"><div class="card"><h3>الاسم والصفحة الرئيسية</h3>${field('اسم المنصة / المدرسة','settingName',config.name)}${field('العنوان الفرعي','settingSubtitle',config.subtitle)}${field('عنوان الصفحة الرئيسية','settingHero',config.hero)}<label for="settingDescription">وصف الصفحة</label><textarea id="settingDescription">${esc(config.description)}</textarea><div class="two-col"><div>${field('اللون الأساسي','settingPrimary',config.primary,'color')}</div><div>${field('لون الخلفية','settingBackground',config.background,'color')}</div></div>${field('رابط الشعار','settingLogo',config.logo||'')}<label for="logoFile">أو ارفع الشعار</label><input id="logoFile" type="file" accept="image/png,image/jpeg,image/webp"><h3>من نحن وتواصل معنا</h3><label for="settingAbout">نبذة عن المنصة</label><textarea id="settingAbout">${esc(config.about||config.description)}</textarea><label for="settingContact">نص التواصل (البريد أو الهاتف أو تعليمات التواصل)</label><textarea id="settingContact">${esc(config.contactText||'')}</textarea>${field('نص أسفل الموقع','settingFooter',config.footerText||'')}<label>القنوات الرسمية وروابط التواصل</label><p class="help">أضف واتساب أو يوتيوب أو أي قناة برابط https://. الروابط الظاهرة تُعرض في قسم من نحن وأسفل الموقع.</p><div id="socialRows"></div>${button('＋ إضافة رابط','addSocial','','quiet')}<label>الأقسام الظاهرة وترتيبها بالأسهم</label><div id="sectionRows"></div><div class="row" style="margin-top:22px">${button('معاينة التغييرات','previewSettings','','outline')}<button>حفظ ونشر الهوية</button></div></div><aside><div id="settingsPreview" class="settings-preview"><h2>${esc(config.name)}</h2><p>${esc(config.hero)}</p><span class="button">نموذج زر</span></div><p class="help">تُحفظ آخر 10 نسخ من الإعدادات للاستعادة.</p>${adminPanel?'':'<a href="admin/admin.html" class="button outline">لوحة التحكم</a>'}</aside></form>`;drawSettingsRows();}
function drawSettingsRows(){$('socialRows').innerHTML=(settingsDraft.socials||[]).map((s,i)=>`<div class="card" style="padding:12px;margin:8px 0"><input data-social="label" data-index="${i}" value="${esc(s.label)}" aria-label="اسم الرابط"><input data-social="url" data-index="${i}" value="${esc(s.url)}" placeholder="https://" aria-label="الرابط"><div class="row">${button('↑','socialUp',i,'quiet')}${button('حذف','socialDelete',i,'outline')}<label class="check"><input data-social="visible" data-index="${i}" type="checkbox" ${s.visible!==false?'checked':''}>ظاهر</label></div></div>`).join('');const order=[...settingsDraft.sections,...['games','videos','about'].filter(k=>!settingsDraft.sections.includes(k))];$('sectionRows').innerHTML=order.map(k=>`<div class="row" style="margin:8px 0"><label class="check"><input data-section="${k}" type="checkbox" ${settingsDraft.sections.includes(k)?'checked':''}>${{games:'الألعاب',videos:'الفيديوهات',about:'عن المنصة'}[k]}</label>${button('↑','sectionUp',k,'quiet')}</div>`).join('');}
function readSettings(){return {...settingsDraft,name:$('settingName').value.trim(),subtitle:$('settingSubtitle').value,hero:$('settingHero').value,description:$('settingDescription').value,primary:$('settingPrimary').value,background:$('settingBackground').value,logo:$('settingLogo').value.trim(),about:$('settingAbout').value.trim(),contactText:$('settingContact').value.trim(),footerText:$('settingFooter').value.trim()};}
async function openAssignment(code,mode='home'){assignment=await api('open',{code});assignment.code=code;assignment.mode=mode;selected=assignment.settings.templates[0];renderJoin();}
function renderJoin(){show(`<section class="game-layout"><span class="eyebrow">${esc(assignment.class_name)} · ${assignment.mode==='group'?'لعب جماعي على السبورة':assignment.mode==='individual'?'لعب فردي في الصف':'واجب منزلي'}</span><h1>${esc(assignment.title)}</h1>${assignment.videos.length?`<div class="card"><h3>قبل أن تبدأ</h3><div class="row">${assignment.videos.map(v=>button('▷ '+esc(v.title),'taskVideo',v.id,'quiet')).join('')}</div></div>`:''}<form id="startForm"><div class="card" style="margin-top:20px">${assignment.mode!=='group'?field('اسم الطالب','studentName',localStorage.getItem('abuobaid_student_name')||''):'<p>تُحتسب هذه الجلسة ضمن إنجاز المعلم فقط.</p>'}<h3>اختر طريقة اللعب</h3><div class="template">${assignment.settings.templates.map(k=>`<button type="button" data-action="selectTemplate" data-id="${k}" class="${k===selected?'selected':''}"><b>${gameIcon(k)}</b>${games[k][1]}</button>`).join('')}</div><label for="questionType">نوع الأسئلة</label><select id="questionType"><option value="">كل الأنواع المتاحة</option>${assignment.types.filter(t=>assignment.settings.types.includes(t)).map(t=>`<option value="${t}">${types[t]||esc(t)}</option>`).join('')}</select><button style="margin-top:22px;width:100%">ابدأ التحدّي ←</button></div></form></section>`);}
function arena(){const n=play?.correct||0,total=play?.questions.length||5,progress=Math.round(n/total*100),k=play?.template||selected;let scene='';
if(k==='race')scene=`<rect x="0" y="72" width="600" height="85" rx="15" fill="#dfd8dc"/><path d="M0 114H600" stroke="white" stroke-width="3" stroke-dasharray="20 16"/><path d="M550 72V157" stroke="#8a1538" stroke-width="8" stroke-dasharray="9 8"/><g class="moving" transform="translate(${20+progress*4.7} 95)"><rect width="60" height="30" rx="12" fill="var(--primary)"/><rect x="18" y="5" width="23" height="20" rx="5" fill="white"/><circle cx="12" cy="0" r="6" fill="#38313b"/><circle cx="47" cy="0" r="6" fill="#38313b"/><circle cx="12" cy="30" r="6" fill="#38313b"/><circle cx="47" cy="30" r="6" fill="#38313b"/></g>`;
else if(k==='football')scene=`<rect x="20" y="30" width="560" height="160" rx="18" fill="#e2eee5"/><path d="M300 30V190M480 60H560V160H480Z" fill="none" stroke="#75937b" stroke-width="3"/><circle cx="300" cy="110" r="45" fill="none" stroke="#75937b"/><text x="${play?.lastCorrect?510:110}" y="130" font-size="48" class="moving">⚽</text><text x="50" y="60" fill="#36563e" font-size="18">${n} أهداف</text>`;
else if(k==='basketball')scene=`<rect x="40" y="32" width="520" height="155" rx="16" fill="#f0dfce"/><path d="M510 40V165M465 45H530V85H465Z" fill="none" stroke="#7b5d48" stroke-width="5"/><ellipse cx="480" cy="92" rx="25" ry="7" fill="none" stroke="#8a1538" stroke-width="5"/><path d="M458 97L468 122H492L503 97" fill="none" stroke="#fff" stroke-width="3"/><text x="${play?.lastCorrect?460:100}" y="${play?.lastCorrect?88:155}" font-size="43" class="moving">🏀</text>`;
else if(k==='volleyball')scene=`<rect x="25" y="155" width="550" height="30" fill="#eadbb8"/><path d="M300 45V170M300 60H410V125H300M320 60V125M345 60V125M370 60V125M395 60V125M300 80H410M300 100H410" stroke="#9f8390" fill="none" stroke-width="3"/><text x="${play?.lastCorrect?455:100}" y="${play?.lastCorrect?110:150}" font-size="50" class="moving">🏐</text>`;
else if(k==='bowling')scene=`<path d="M50 175L145 40H455L550 175Z" fill="#ecdfce"/>${Array.from({length:10},(_,i)=>`<text x="${245+(i%4)*25}" y="${60+Math.floor(i/4)*35}" font-size="28" opacity="${i<Math.ceil(progress/10)?.16:1}">♟</text>`).join('')}<circle cx="${play?.lastCorrect?300:95}" cy="${play?.lastCorrect?90:155}" r="17" fill="var(--primary)" class="moving"/>`;
else if(k==='fishing')scene=`<path d="M0 100Q30 80 60 100T120 100T180 100T240 100T300 100T360 100T420 100T480 100T540 100T600 100V210H0Z" fill="#d7edf0"/><path d="M120 40L320 25L330 135" stroke="#795943" stroke-width="3" fill="none"/>${Array.from({length:5},(_,i)=>`<text x="${60+i*100}" y="160" font-size="30" opacity="${i<Math.ceil(progress/20)?.2:1}">🐟</text>`).join('')}<text x="440" y="65" font-size="20" fill="var(--primary)">${n} صيد ناجح</text>`;
else if(k==='puzzle')scene=`<text x="220" y="145" font-size="95">🏫</text>${Array.from({length:12},(_,i)=>`<rect x="${180+(i%4)*60}" y="${30+Math.floor(i/4)*50}" width="58" height="48" rx="5" fill="var(--primary)" opacity="${i<Math.ceil(progress/100*12)?0:1}"/>`).join('')}`;
else scene=`<circle cx="300" cy="110" r="70" fill="#f0e0e6"/><text x="300" y="130" text-anchor="middle" font-size="48" fill="var(--primary)">${n}</text>`;
return `<div class="arena"><span class="arena-caption">${games[k][1]} · ${n} إجابات صحيحة</span><svg viewBox="0 0 600 210" role="img" aria-label="تقدم اللعبة ${progress}%">${scene}</svg></div>`;}
function questionUI(q){if(['multiple_choice','true_false'].includes(q.type))return `<div class="answers">${(q.options||['صح','خطأ']).map((o,i)=>button(esc(o),'answer',i)).join('')}</div>`;
if(['open_text','short_answer'].includes(q.type))return '<label for="answerText">اكتب إجابتك</label><textarea id="answerText"></textarea>'+button('إرسال الإجابة','textAnswer');
if(['matching','connecting'].includes(q.type))return q.pairs.map((p,i)=>`<label for="match${i}">${esc(p.left)}</label><select id="match${i}"><option value="">اختر…</option>${q.choices.map(c=>`<option>${esc(c)}</option>`).join('')}</select>`).join('')+'<p></p>'+button('تثبيت المطابقة','matchAnswer');
if(q.type==='ordering'){play.order=play.order||[...q.items];return `<p class="help">استخدم ↑ لإعادة ترتيب العناصر.</p><div class="stack">${play.order.map((it,i)=>`<div class="row card" style="padding:10px">${button('↑','orderUp',i,'quiet')}<span>${esc(it)}</span></div>`).join('')}</div><p></p>${button('تثبيت الترتيب','orderAnswer')}`;}
if(q.type==='classification')return q.classItems.map(it=>`<label>${it.image?`<img src="${esc(it.image)}" width="70" alt="عنصر للتصنيف">`:esc(it.text)}</label><select data-class-id="${esc(it.id)}"><option value="">اختر التصنيف…</option>${q.categories.map((c,i)=>`<option value="${i}">${esc(c.title)}</option>`).join('')}</select>`).join('')+'<p></p>'+button('تثبيت التصنيف','classAnswer');
if(q.type==='puzzle_image')return '<iframe id="originalPuzzle" title="بازل الصورة" src="games/puzzle.html" style="width:100%;height:72vh;border:0;border-radius:15px" allow="fullscreen"></iframe>';
if(q.type==='puzzle_grid_fallback'){const n=Number(q.puzzle_grid)||3;play.tiles=play.tiles||M.shuffle(Array.from({length:n*n},(_,i)=>i));return `<p class="help">اضغط قطعتين لتبديلهما حتى تكتمل الصورة.</p><div class="puzzle-board" style="grid-template-columns:repeat(${n},1fr)">${play.tiles.map((tile,pos)=>`<button data-action="tile" data-id="${pos}" class="${play.tile===pos?'selected':''}" aria-label="القطعة ${pos+1}" style="background-image:url('${esc(q.image).replace(/'/g,'%27')}');background-size:${n*100}%;background-position:${tile%n/(n-1)*100}% ${Math.floor(tile/n)/(n-1)*100}%"></button>`).join('')}</div>${button('تحقق من الصورة','puzzleAnswer')}`;}
return '<p>هذا النوع يحتاج مراجعة المعلم.</p>'+button('إرسال للمراجعة','textAnswer');}
function renderQuestion(){const q=play.questions[play.index];const render=['race','football','basketball','bowling','volleyball','fishing','puzzle','classic'].includes(play.template)?dialog:show;render(`${gameHUD()}<section class="game-layout"><div class="game-top"><b>${esc(assignment.title)}</b><span>${play.index+1} / ${play.questions.length}</span></div><div class="progress"><span style="width:${play.index/play.questions.length*100}%"></span></div>${['race','football','basketball','bowling','volleyball','fishing','puzzle','classic'].includes(play.template)?'':arena()}<article class="card"><span class="tag">${types[q.type]||'سؤال'}</span><h2 class="question">${esc(q.text)}</h2>${q.image&&q.type!=='puzzle_image'?`<img src="${esc(q.image)}" alt="صورة السؤال" style="max-width:100%;max-height:220px">`:''}<div id="answerArea">${questionUI(q)}</div><div id="feedback"></div></article></section>`);}
async function answer(value){if(play.answered||play.answerPending)return;play.answerPending=true;try{const q=play.questions[play.index],r=await api('answer',{id:play.id,secret:play.secret,question:q.id,value});play.answered=true;play.points=(play.points||0)+(Number(r.points)||0);play.completed=(play.completed||0)+1;play.pendingCount=(play.pendingCount||0)+(r.pending?1:0);updateGameHUD();play.lastCorrect=r.correct;if(r.correct)play.correct++;if(['football','basketball','bowling','volleyball','fishing','puzzle','classic'].includes(play.template)){close();$(play.template+'Game').contentWindow.postMessage({type:'school-'+play.template+'-result',token:play.sportToken,index:play.index,correct:r.correct,pending:r.pending,feedback:[r.feedback,r.explanation].filter(Boolean).join(' ')},location.origin);return;}$('answerArea').querySelectorAll('button,input,textarea,select').forEach(el=>el.disabled=true);$('feedback').innerHTML=`<div class="feedback ${!r.correct&&!r.pending?'wrong':''}"><b>${esc(r.feedback)}</b><p>${esc(r.explanation)}</p></div>${button(play.template==='race'?'واصل السباق ←':play.index===play.questions.length-1?'عرض النتيجة':'السؤال التالي ←','next')}`;if(document.querySelector('.arena'))document.querySelector('.arena').outerHTML=arena();}finally{play.answerPending=false;}}
async function finish(){const r=await api('finish',{id:play.id,secret:play.secret});show(`<section class="auth card" style="text-align:center;max-width:650px"><span class="eyebrow">${esc(assignment.title)}</span><h1>${r.group?'اكتملت الجلسة الصفية':r.pending?'أحسنت، وصلت إجاباتك':r.passed?'أحسنت! اجتزت المهمة':'تجربة مفيدة، واصل التعلّم'}</h1>${r.group?'<p>سُجّلت جلسة جماعية في إنجاز المعلم دون درجات فردية للطلاب.</p>':`<div class="result-score">${r.score}%</div><p>${r.pending?'الدرجة مبدئية حتى مراجعة الأسئلة المقالية.':'درجة الاجتياز '+play.threshold+'%'}</p>`}<div class="row" style="justify-content:center">${button('العودة للمهمة','replay','','quiet')}${!r.group?button('قائمة الصدارة','leaderboard'):''}</div><div id="leaderboardResults"></div></section>`);}
function exportCSV(){const id=$('reportAssignment').value,rows=data.sessions.filter(s=>s.mode!=='group'&&(!id||s.assignment_id===id));const safe=v=>'"'+String(v??'').replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const values=[['الطالب','المهمة','الصف','المكان','الدرجة','الحالة','التاريخ'],...rows.map(s=>{const a=data.assignments.find(a=>a.id===s.assignment_id);return[s.student_name,a?.title,a?.class_name,s.mode==='home'?'المنزل':'الصف',s.score,s.pending?'بانتظار التصحيح':s.finished_at?'مكتملة':'غير مكتملة',s.created_at];})];M.downloadFile('سجل-إنجاز-الطلاب.csv','\ufeff'+values.map(r=>r.map(safe).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action,id=b.dataset.id;e.preventDefault();run(async()=>{
if(a==='raceQuestion'){if(play?.raceQuestion)renderQuestion();else notice('قد السيارة إلى الحاجز الأول.');}else if(a==='dashboard')await dashboard();else if(a==='login')auth();else if(a==='signup')auth(true);else if(a==='joinFocus')$('joinCode').focus();else if(a==='tab'){tab=id;renderDashboard();}else if(a==='assign')assignmentForm(id);else if(a==='copy'){const u=link(data.assignments.find(x=>x.id===id));try{await navigator.clipboard.writeText(u);notice('تم نسخ رابط المهمة.');}catch{dialog(`<h2>رابط المهمة</h2><input class="link-field" readonly value="${esc(u)}">`);}}
else if(a==='toggle'){const x=data.assignments.find(x=>x.id===id);await api('toggleAssignment',{id,active:!x.active});await dashboard();}
else if(a==='class'){const x=data.assignments.find(x=>x.id===id);dialog(`<h2>طريقة التشغيل الصفي</h2><p>الجماعي إنجاز للمعلم فقط. الفردي يسجّل باسم الطالب.</p><div class="row">${button('جماعي على السبورة','classGroup',x.id)}${button('فردي باسم الطالب','classIndividual',x.id,'quiet')}</div>`);}
else if(a==='classGroup'||a==='classIndividual'){close();await openAssignment(data.assignments.find(x=>x.id===id).code,a==='classGroup'?'group':'individual');}
else if(a==='addVideo')videoForm();else if(a==='watch')watch(data.videos.find(v=>v.id===id));else if(a==='taskVideo')watch(assignment.videos.find(v=>v.id===id));else if(a==='deleteVideo'){dialog(`<h2>حذف الفيديو؟</h2><p>سيختفي الرابط من مهماتك.</p>${button('تأكيد الحذف','confirmDeleteVideo',id)}`);}else if(a==='confirmDeleteVideo'){await api('deleteVideo',{id});close();await dashboard();}
else if(a==='review')await review(id);else if(a==='student')studentRecord(id);else if(a==='export')exportCSV();else if(a==='reset')dialog(`<h2>إعادة تعيين كلمة المرور</h2><form id="resetForm" data-id="${id}">${field('كلمة المرور الجديدة (8 أحرف على الأقل)','newPassword','','password')}<button style="margin-top:15px">حفظ كلمة المرور</button></form>`);
else if(a==='role'){const t=data.teachers.find(t=>t.id===id),role=t.role==='admin'?'teacher':'admin';if(!confirm(role==='admin'?'منح هذا الحساب صلاحية إدارة المنصة بالكامل؟':'إلغاء صلاحية الإدارة وتحويل الحساب إلى معلم؟'))return;await api('setRole',{id,role});await dashboard();}
else if(a==='teacherStatus'){const t=data.teachers.find(t=>t.id===id);await api('teacherStatus',{id,active:t.status==='موقوف'});await dashboard();}
else if(a==='addSocial'){settingsDraft.socials.push({label:'رابط جديد',url:'https://',visible:true});drawSettingsRows();}else if(a==='socialDelete'){settingsDraft.socials.splice(Number(id),1);drawSettingsRows();}else if(a==='socialUp'){const i=Number(id);if(i>0)[settingsDraft.socials[i-1],settingsDraft.socials[i]]=[settingsDraft.socials[i],settingsDraft.socials[i-1]];drawSettingsRows();}
else if(a==='sectionUp'){const i=settingsDraft.sections.indexOf(id);if(i>0)[settingsDraft.sections[i-1],settingsDraft.sections[i]]=[settingsDraft.sections[i],settingsDraft.sections[i-1]];drawSettingsRows();}
else if(a==='previewSettings'){const c=readSettings();$('settingsPreview').style.setProperty('--primary',c.primary);$('settingsPreview').style.background=c.background;$('settingsPreview').innerHTML=`${c.logo?`<img src="${esc(c.logo)}" alt="معاينة الشعار" style="width:65px;height:65px;object-fit:contain">`:''}<h2>${esc(c.name)}</h2><small>${esc(c.subtitle)}</small><h3>${esc(c.hero)}</h3><p>${esc(c.description)}</p><h3>من نحن</h3><p>${esc(c.about)}</p><p>${esc(c.contactText)}</p><div class="row">${c.socials.filter(s=>s.visible!==false).map(s=>`<span class="tag">${esc(s.label)}</span>`).join('')}</div><p>${esc(c.footerText)}</p><span class="button">نموذج زر</span>`;}
else if(a==='history'){const h=await api('settingsHistory');dialog(`<h2>الإعدادات السابقة</h2>${h.length?h.map((v,i)=>`<div class="card row"><span>${esc(v.data.name)} · ${new Date(v.at).toLocaleString('ar-QA')}</span>${button('استعادة','restore',i,'quiet')}</div>`).join(''):'لا توجد نسخ سابقة بعد.'}`);}
else if(a==='restore'){await api('restoreSettings',{index:Number(id)});config=await api('settings');applyBrand(config);close();renderSettings();notice('تمت استعادة الإعدادات.');}
else if(a==='selectTemplate'){selected=id;document.querySelectorAll('[data-action=selectTemplate]').forEach(x=>x.classList.toggle('selected',x.dataset.id===id));}
else if(a==='answer')await answer(Number(id));else if(a==='textAnswer')await answer($('answerText')?.value||'');else if(a==='matchAnswer'){const q=play.questions[play.index],v=q.pairs.map((_,i)=>$('match'+i).value);if(v.some(x=>!x))throw new Error('أكمل كل الاختيارات.');await answer(v);}
else if(a==='classAnswer'){const v={};for(const x of document.querySelectorAll('[data-class-id]')){if(x.value==='')throw new Error('صنّف كل العناصر.');v[x.dataset.classId]=Number(x.value);}await answer(v);}
else if(a==='orderUp'){const i=Number(id);if(i>0)[play.order[i-1],play.order[i]]=[play.order[i],play.order[i-1]];$('answerArea').innerHTML=questionUI(play.questions[play.index]);}
else if(a==='orderAnswer')await answer(play.order);else if(a==='tile'){const i=Number(id);if(play.tile===undefined)play.tile=i;else{[play.tiles[i],play.tiles[play.tile]]=[play.tiles[play.tile],play.tiles[i]];play.tile=undefined;}$('answerArea').innerHTML=questionUI(play.questions[play.index]);}
else if(a==='puzzleAnswer')await answer(play.tiles);else if(a==='next'){if(play.template==='race'){play.raceQuestion=false;close();$('originalRace').contentWindow.postMessage({type:'school-race-continue',correct:play.lastCorrect},location.origin);return;}if(play.index===play.questions.length-1)await finish();else{play.index++;play.answered=false;play.order=null;play.tiles=null;play.tile=undefined;renderQuestion();}}
else if(a==='replay'){if(play?.demo)startDemo(play.template);else renderJoin();}else if(a==='leaderboard'){const rows=await api('leaderboard',{id:play.id,secret:play.secret});$('leaderboardResults').innerHTML=`<h3>قائمة الصدارة</h3>${rows.length?rows.map((r,i)=>`<div class="row card" style="justify-content:space-between;margin-top:8px"><span>${i+1}. ${esc(r.student_name)}</span><b>${r.score}%</b></div>`).join(''):'لا توجد نتائج نهائية منشورة بعد.'}`;}
},b);});
document.addEventListener('submit',e=>{const f=e.target;if(!['joinForm','authForm','assignmentForm','videoForm','renameForm','resetForm','settingsForm','startForm'].includes(f.id)&&!f.classList.contains('gradeForm'))return;e.preventDefault();run(async()=>{
if(f.id==='joinForm'){let code=$('joinCode').value.trim();try{code=new URL(code).searchParams.get('task')||code;}catch{}await openAssignment(code);history.replaceState(null,'','?task='+encodeURIComponent(code));}
else if(f.id==='authForm'){const username=$('username').value.trim(),password=$('password').value;if(f.dataset.signup==='true')await api('register',{username,password,name:$('fullName').value});const r=await api('loginAlias',{username});await M.authSignIn({email:r.email,password});await navigation();await dashboard();const next=new URLSearchParams(location.search).get('next');if(data.profile.admin&&next==='admin')location.href='admin/admin.html';}
else if(f.id==='assignmentForm'){const r=await api('assignment',{game_id:f.dataset.game,title:$('assignmentTitle').value,class_name:$('className').value,templates:[...f.querySelectorAll('[name=templates]:checked')].map(x=>x.value),types:[...f.querySelectorAll('[name=types]:checked')].map(x=>x.value),passing_score:$('passingScore').value,deadline:$('deadline').value?new Date($('deadline').value).toISOString():null,leaderboard:$('leaderboard').checked});close();tab='assignments';await dashboard();dialog(`<h2>المهمة جاهزة</h2><p>أرسل هذا الرابط لطلابك. يدخلون بالاسم فقط.</p><input class="link-field" readonly value="${esc(link(r))}"><p></p>${button('نسخ الرابط','copy',r.id)}`);}
else if(f.id==='videoForm'){let url=$('videoUrl').value.trim();const file=$('videoFile').files[0];if(file){if(file.size>40*1024*1024)throw new Error('الحد الأقصى للفيديو 40 MB.');if(!['video/mp4','video/webm'].includes(file.type))throw new Error('ارفع MP4 أو WebM.');const uploaded=await M.cloudUploadFile(file,{folder:'school-videos'});url=uploaded.url||uploaded.publicUrl||uploaded;}await api('video',{title:$('videoTitle').value,subject:$('videoSubject').value,url,game_id:$('videoGame').value});close();await dashboard();}
else if(f.id==='renameForm'){await api('renameStudent',{id:f.dataset.id,name:$('correctedName').value,student_key:$('mergeKey').value});close();await dashboard();}
else if(f.id==='resetForm'){await api('resetPassword',{id:f.dataset.id,password:$('newPassword').value});close();notice('تم تغيير كلمة مرور المعلم.');}
else if(f.classList.contains('gradeForm')){await api('grade',{id:f.dataset.id,question:f.dataset.q,points:f.elements.points.value,feedback:f.elements.feedback.value});notice('تم اعتماد الدرجة.');await review(f.dataset.id);data=await api('dashboard');}
else if(f.id==='settingsForm'){const c=readSettings();await api('saveSettings',{data:c});config=c;applyBrand(c);if(adminPanel)parent.postMessage({type:'school-settings-saved'},location.origin);notice('حُفظت الهوية ونُشرت.');}
else if(f.id==='startForm'){const name=$('studentName')?.value||'';let key=localStorage.getItem('abuobaid_student_key');if(!key||localStorage.getItem('abuobaid_student_name')!==name)key=crypto.randomUUID();play=await api('start',{code:assignment.code,mode:assignment.mode,name,student_key:key,template:selected,type:$('questionType').value});Object.assign(play,{index:0,correct:0,points:0,completed:0,pendingCount:0,template:selected});if(assignment.mode!=='group'){localStorage.setItem('abuobaid_student_name',name);localStorage.setItem('abuobaid_student_key',key);}if(play.template==='race')renderRace();else if(['football','basketball','bowling','volleyball','fishing','puzzle','classic'].includes(play.template))renderSport();else renderQuestion();}
},f.querySelector('button[type=submit]')||f.querySelector('button:last-child'));});
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.social&&settingsDraft){const s=settingsDraft.socials[Number(el.dataset.index)];if(s)s[el.dataset.social]=el.type==='checkbox'?el.checked:el.value;}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='reportAssignment')renderReports();if(el.dataset.social){const s=settingsDraft.socials[Number(el.dataset.index)];s[el.dataset.social]=el.type==='checkbox'?el.checked:el.value;}if(el.dataset.section){settingsDraft.sections=settingsDraft.sections.filter(k=>k!==el.dataset.section);if(el.checked)settingsDraft.sections.push(el.dataset.section);}if(el.id==='logoFile')run(async()=>{const file=el.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw new Error('ارفع PNG أو JPG أو WebP.');$('settingLogo').value=await M.compressImageFile(file,300,.8);});});
$('closeModal').onclick=close;$('dashboardLink').onclick=()=>run(dashboard);$('loginLink').onclick=()=>M.isAuthenticated()?M.authSignOut():auth();
function renderSport(){play.sportToken=crypto.randomUUID();play.sportOutcome=false;const sport=play.template;show(`${gameHUD()}<section class="football-host"><iframe id="${sport}Game" title="${esc(games[sport][1])}" src="games/${sport}/index.html" style="width:100%;height:85svh;min-height:440px;border:0;border-radius:18px" allow="fullscreen;autoplay" allowfullscreen></iframe></section>`);}
window.addEventListener('message',e=>{if(!play||!['football','basketball','bowling','volleyball','fishing','puzzle','classic'].includes(play.template))return;const sport=play.template,frame=$(sport+'Game'),prefix='school-'+sport+'-';if(!frame||e.origin!==location.origin||e.source!==frame.contentWindow)return;const b=e.data;if(!b||typeof b!=='object')return;if(b.type===prefix+'ready'){frame.contentWindow.postMessage({type:prefix+'config',title:assignment.title,count:play.questions.length,images:play.questions.map(q=>q.image||''),token:play.sportToken},location.origin);return;}if(b.token!==play.sportToken||b.index!==play.index)return;if(b.type===prefix+'question'&&!play.answered&&!play.answerPending)renderQuestion();if(b.type===prefix+'outcome'&&play.answered)play.sportOutcome=true;if(b.type===prefix+'fullscreen'){run(async()=>{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();});}if(b.type===prefix+'next'&&play.answered&&play.sportOutcome){play.sportOutcome=false;run(async()=>{if(play.index===play.questions.length-1){try{await finish();}catch(e){play.sportOutcome=true;frame.contentWindow.postMessage({type:prefix+'retry',token:play.sportToken,index:play.index},location.origin);throw e;}}else{const oldIndex=play.index;play.index++;play.answered=false;play.order=null;play.tiles=null;play.tile=undefined;frame.contentWindow.postMessage({type:prefix+'advance',token:play.sportToken,index:oldIndex},location.origin);}});}});
function renderRace(){show(`${gameHUD()}<section><div class="row" style="justify-content:space-between"><h2>${esc(assignment.title)}</h2>${button('عرض السؤال الحالي','raceQuestion','','quiet')}</div><iframe id="originalRace" title="سباق الأبطال ثلاثي الأبعاد" src="games/race.html" style="width:100%;height:78vh;border:0;border-radius:18px" allow="fullscreen;autoplay"></iframe><p class="help">التحكم باللمس في مساحة السباق أو بأسهم لوحة المفاتيح. افتح السؤال عند الوصول إلى الحاجز.</p></section>`);}
window.addEventListener('message',e=>{if(e.origin!==location.origin)return;const race=$('originalRace'),puzzle=$('originalPuzzle');if(race&&e.source===race.contentWindow){if(e.data?.type==='school-race-ready')race.contentWindow.postMessage({type:'school-race-config',school:config.name,title:assignment.title,count:play.questions.length,teacher:assignment.teacher||'',subject:assignment.subject||''},location.origin);if(e.data?.type==='school-race-fullscreen')run(async()=>{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();});if(e.data?.type==='school-race-question'){play.index=e.data.index;play.answered=false;play.order=null;play.tiles=null;play.raceQuestion=true;renderQuestion();}if(e.data?.type==='school-race-finished')run(finish);}
if(puzzle&&e.source===puzzle.contentWindow){const q=play.questions[play.index];if(e.data?.type==='school-puzzle-ready')puzzle.contentWindow.postMessage({type:'school-puzzle-config',image:q.image,title:assignment.title,school:config.name,pieces:Number(q.puzzle_grid)===3?9:Number(q.puzzle_grid)===4?16:6},location.origin);if(e.data?.type==='school-puzzle-complete')run(()=>answer(Array.from({length:(Number(q.puzzle_grid)||3)**2},(_,i)=>i)));}});
window.School={api,home,dashboard,openAssignment,arena,gradeUI:questionUI};
(async()=>{if(!adminPanel)navigation();try{config=await api('settings');}catch(e){notice('تعذر تحميل الإعدادات: '+e.message);}applyBrand(config);const params=new URLSearchParams(location.search);if(params.has('task'))await run(()=>openAssignment(params.get('task')));else if(params.has('dashboard')||adminPanel)await run(dashboard);else if(params.has('login'))auth();else if(params.has('demo'))startDemo(params.get('demo'));else home();})();
})();
